setTimeout(function(){var l=document.getElementById('app-loader');if(l){l.classList.add('hidden');setTimeout(function(){l.remove()},500)}},400);

function setupScrollSpy(){var sections=document.querySelectorAll('section[id],.hero[id]');var sbLinks=document.querySelectorAll('.sb-link[data-section]');var tbLinks=document.querySelectorAll('.topbar-link[data-section]');if(!sections.length)return;var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){var id=entry.target.id;sbLinks.forEach(function(l){var match=l.dataset.section===id||(id==='topics'&&['simulations','labs','videos'].indexOf(l.dataset.section)!==-1);l.classList.toggle('active',match)});tbLinks.forEach(function(l){var match=l.dataset.section===id||(id==='topics'&&['simulations','labs','videos'].indexOf(l.dataset.section)!==-1);l.classList.toggle('active',match)})}})},{rootMargin:'-20% 0px -60% 0px',threshold:0});sections.forEach(function(s){observer.observe(s)})}

function setupSectionReveal(){var sections=document.querySelectorAll('section[id]');sections.forEach(function(s){s.classList.add('section-reveal')});var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{rootMargin:'0px 0px -80px 0px',threshold:0.05});sections.forEach(function(s){observer.observe(s)})}

function parseMd(text){return text.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n- /g,'\n<span class="md-bullet">•</span> ').replace(/\n(\d+)\. /g,'\n<span class="md-num">$1.</span> ').replace(/\n\n/g,'<br><br>').replace(/\n/g,'<br>')}

function buildApp(){var root=document.getElementById('root');var totalLessons=C.topics.reduce(function(a,t){return a+t.lessons.length},0);C.hero.stats=[{text:C.topics.length+' Temas'},{text:totalLessons+' Lecciones'},{text:(C.simulations.length+(C.customSims||[]).length)+' Simuladores'},{text:C.videos.length+' Videos'}];var sidebarLinks=(C.nav||[]).map(function(n){return '<button class="sb-link" data-section="'+(n.href||'').replace('#','')+'"><span class="sb-icon">'+n.icon+'</span>'+n.label+'</button>'}).join('');root.innerHTML='<nav class="sidebar" id="sidebar"><div class="sb-head"><div class="logo-text">⚗️ '+C.site.name+'</div><p>'+(C.site.tagline||C.site.description)+'</p></div><div class="sb-nav"><div class="sb-section">Navegación</div><button class="sb-link active" data-section="hero"><span class="sb-icon">🏠</span>Inicio</button>'+sidebarLinks+'<div class="sb-section">Más</div><button class="sb-link" data-section="faqs"><span class="sb-icon">❓</span>Preguntas</button><button class="sb-link" data-section="contact"><span class="sb-icon">💬</span>Contacto</button></div><div class="sb-foot"><strong>'+C.site.name+'</strong>© '+C.site.year+' · v'+(C.site.version||'2.0')+'</div></nav><div class="sb-overlay" id="sb-overlay"></div><div class="main-wrap"><div class="topbar" id="topbar"><button class="topbar-toggle" id="topbar-toggle">☰</button><span class="topbar-title">'+C.site.name+'</span><span class="topbar-badge">v'+(C.site.version||'2.0')+'</span><div class="topbar-nav">'+(C.nav||[]).map(function(n){return '<button class="topbar-link" data-section="'+(n.href||'').replace('#','')+'">'+n.icon+' '+n.label+'</button>'}).join('')+'</div></div><section class="hero" id="hero"><div class="container"><div class="hero-grid"><div><div class="hero-badge"><div class="pulse"></div>'+C.hero.badge+'</div><h1>'+C.hero.title+'</h1><p class="hero-desc">'+C.hero.subtitle+'</p><div class="hero-actions">'+(C.hero.cta||[]).map(function(b){return '<button class="btn btn-'+b.style+'" data-action="'+b.target+'">'+b.text+'</button>'}).join('')+'</div><div class="hero-stats">'+C.hero.stats.map(function(s){return '<div class="stat">'+s.text+'</div>'}).join('')+'</div></div><div class="hero-cards">'+(C.hero.cards||[]).map(function(c){return '<div class="hero-card"><div class="hc-icon">'+c.icon+'</div><div class="hc-title">'+c.title+'</div><div class="hc-desc">'+c.desc+'</div></div>'}).join('')+'</div></div></div><div class="hero-wave"><svg viewBox="0 0 1440 60" preserveAspectRatio="none"><path d="M0,40 C360,80 720,0 1440,40 L1440,60 L0,60 Z" fill="var(--bg)"/></svg></div></section><section id="topics" class="content-hub"><div class="container"><div class="section-header"><div class="section-tag">Explorar</div><h2 class="section-title">Contenido</h2><p class="section-desc">Temas, simuladores, prácticas y clases en video — todo en un solo lugar.</p></div><div class="hub-tabs" id="hub-tabs"><button class="hub-tab active" data-tab="tab-topics">📚 Temas</button><button class="hub-tab" data-tab="tab-sims">🧪 Simuladores</button><button class="hub-tab" data-tab="tab-labs">🔬 Experimentos</button><button class="hub-tab" data-tab="tab-videos">🎬 Videos</button></div><div id="hub-panels"><div class="hub-panel active" id="tab-topics"><div class="hub-panel-desc">'+C.sections.topics.desc+'</div><div class="grid-3" id="topics-grid"></div></div><div class="hub-panel" id="tab-sims"><div class="hub-panel-desc">'+C.sections.simulations.desc+'</div><div class="grid-3" id="sims-grid"></div></div><div class="hub-panel" id="tab-labs"><div class="hub-panel-desc">'+C.sections.labs.desc+'</div><div class="grid-3" id="labs-grid"></div></div><div class="hub-panel" id="tab-videos"><div class="hub-panel-desc">'+C.sections.videos.desc+'</div><div class="grid-3" id="videos-grid"></div></div></div></div></section><span id="simulations"></span><span id="labs"></span><span id="videos"></span><section id="periodic"><div class="container"><div class="section-header"><div class="section-tag">'+C.sections.periodic.tag+'</div><h2 class="section-title">'+C.sections.periodic.title+'</h2><p class="section-desc">'+C.sections.periodic.desc+'</p></div><div id="pt-wrapper"></div></div></section><section id="faqs"><div class="container"><div class="section-header"><div class="section-tag">Preguntas</div><h2 class="section-title">Preguntas Frecuentes</h2><p class="section-desc">Respuestas a las dudas más comunes.</p></div><div id="faq-list"></div></div></section><section id="contact"><div class="container"><div class="section-header"><div class="section-tag">Contacto</div><h2 class="section-title">Contacto</h2><p class="section-desc">Escríbenos tus dudas.</p></div><div id="contact-form-container"></div></div></section><footer></footer></div><div class="modal-overlay" id="topic-modal"><div class="modal" id="topic-modal-content"></div></div><div class="modal-overlay" id="lesson-modal"><div class="modal" id="lesson-modal-content"></div></div><div class="modal-overlay" id="lab-modal"><div class="modal" id="lab-modal-content"></div></div><div class="modal-overlay" id="sim-modal"><div class="modal" id="sim-modal-content"></div></div><div class="modal-overlay" id="video-modal"><div class="modal" id="video-modal-content"></div></div><div class="admin-overlay" id="admin-overlay"><div class="admin-panel"><div class="admin-header"><h2>⚙️ Panel de Administración</h2><div class="admin-header-actions"><button class="admin-apply" id="admin-apply">✅ Aplicar</button><button class="admin-download" id="admin-download">💾 Descargar</button><button class="admin-close" id="admin-close">✕</button></div></div><div class="admin-tabs" id="admin-tabs"></div><div class="admin-body" id="admin-body"></div></div></div><button class="feedback-fab" id="feedback-fab">💬</button><div class="feedback-panel" id="feedback-panel"><div class="feedback-head"><strong>Feedback</strong></div><div id="feedback-body"><div class="feedback-type"><button type="button" class="active" data-type="error">🐛 Error</button><button type="button" data-type="sugerencia">💡 Sugerencia</button></div><textarea class="feedback-textarea" id="feedback-text" placeholder="Describe el error o tu sugerencia..."></textarea><button class="feedback-submit" id="feedback-submit-btn">Enviar</button></div></div><button class="quicknav-fab" id="quicknav-fab">⚡</button><div class="quicknav-panel" id="quicknav-panel"><div class="quicknav-head">Navegación rápida</div>'+(C.nav||[]).map(function(n){return '<button class="quicknav-item" data-section="'+(n.href||'').replace('#','')+'">'+n.icon+'<span>'+n.label+'</span></button>'}).join('')+'<button class="quicknav-item" data-section="faqs">❓<span>Preguntas</span></button><button class="quicknav-item" data-section="contact">💬<span>Contacto</span></button></div><button class="backtop-btn" id="backtop-btn" title="Volver arriba">↑</button>';renderTopics();renderSims();renderLabs();renderVideos();renderPeriodicTable();renderFAQs();renderContactForm()}

function renderTopics(){var grid=document.getElementById('topics-grid');if(!grid)return;grid.innerHTML=C.topics.map(function(t,i){return '<div class="card" data-topic="'+i+'"><div class="card-bar" style="background:linear-gradient(90deg,'+t.color+',transparent)"></div><div class="card-body"><div class="card-icon">'+t.icon+'</div><div class="card-title">'+t.title+'</div><div class="card-desc">'+t.desc+'</div><div class="card-meta"><span class="meta-left">'+t.lessons.length+' lecciones</span><span class="meta-right">'+t.tag+'</span></div></div><div class="card-foot">Explorar <span>→</span></div></div>'}).join('');grid.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openTopic(parseInt(el.dataset.topic))})})}

function renderSims(){var grid=document.getElementById('sims-grid');if(!grid)return;var allSims=C.simulations.concat(C.customSims||[]);grid.innerHTML=allSims.map(function(s){return '<div class="card" data-sim="'+s.id+'"><div class="card-bar" style="background:linear-gradient(90deg,'+(s.color||'var(--cyan)')+',transparent)"></div><div class="card-body"><div class="card-icon">'+s.icon+'</div><div class="card-title">'+s.title+'</div><div class="card-desc">'+s.desc+'</div><div class="card-meta"><span class="meta-left">Interactivo</span><span class="meta-right">'+(s.tag||s.category||'')+'</span></div></div><div class="card-foot">Simular <span>→</span></div></div>'}).join('');grid.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openSim(el.dataset.sim)})})}

function renderLabs(){var grid=document.getElementById('labs-grid');if(!grid)return;grid.innerHTML=(C.labs||[]).map(function(l,i){return '<div class="card" data-lab="'+i+'"><div class="card-bar" style="background:linear-gradient(90deg,'+(l.color||'var(--emerald)')+',transparent)"></div><div class="card-body"><div class="card-icon">'+l.icon+'</div><div class="card-title">'+l.title+'</div><div class="card-desc">'+l.desc+'</div><div class="card-meta"><span class="meta-left">Práctica</span><span class="meta-right">'+l.tag+'</span></div></div><div class="card-foot">Ver guía <span>→</span></div></div>'}).join('');grid.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openLab(parseInt(el.dataset.lab))})})}

function renderVideos(){var grid=document.getElementById('videos-grid');if(!grid)return;grid.innerHTML=C.videos.map(function(v,i){return '<div class="video-card" data-vidx="'+i+'"><div class="video-thumb"><img src="https://img.youtube.com/vi/'+v.youtubeId+'/mqdefault.jpg" alt="'+v.title+'" loading="lazy"><div class="video-play"><div class="video-play-btn">▶</div></div><div class="video-dur">'+v.duration+'</div></div><div class="video-info"><span class="vi-tag">'+v.category+'</span><h3>'+v.title+'</h3><p>'+v.description+'</p></div></div>'}).join('');document.querySelectorAll('.video-card').forEach(function(el){el.addEventListener('click',function(){var v=C.videos[+el.dataset.vidx];openVideo(v.youtubeId,v.title)})})}

function renderPeriodicTable(){var wrapper=document.getElementById('pt-wrapper');if(!wrapper)return;var elMap={};C.elements.forEach(function(el){elMap[el.row+'-'+el.col]=el});function cell(el){if(!el)return '<div class="pt-cell pt-empty"></div>';return '<div class="pt-cell pt-'+el.cat+'" data-z="'+el.z+'" title="'+el.name+' ('+el.sym+') — Z='+el.z+', '+el.mass+' u"><span class="pt-z">'+el.z+'</span><span class="pt-sym">'+el.sym+'</span><span class="pt-name">'+el.name+'</span></div>'}var mainHTML='<div class="pt-row pt-header-row"><div class="pt-period-label"></div>';for(var c=1;c<=18;c++)mainHTML+='<div class="pt-group-label">'+c+'</div>';mainHTML+='</div>';for(var r=1;r<=7;r++){mainHTML+='<div class="pt-row"><div class="pt-period-label">'+r+'</div>';for(var c=1;c<=18;c++){if(r===6&&c===3){mainHTML+='<div class="pt-cell pt-lanthanide pt-ref" data-ref="lan" title="Lantánidos (57-71)"><span class="pt-z">57-71</span><span class="pt-sym">La-Lu</span><span class="pt-name">Lantánidos</span></div>';continue}if(r===7&&c===3){mainHTML+='<div class="pt-cell pt-actinide pt-ref" data-ref="act" title="Actínidos (89-103)"><span class="pt-z">89-103</span><span class="pt-sym">Ac-Lr</span><span class="pt-name">Actínidos</span></div>';continue}mainHTML+=cell(elMap[r+'-'+c])}mainHTML+='</div>'}var lanHTML='<div class="pt-row"><div class="pt-period-label pt-series-label">Lan</div>';for(var c=1;c<=18;c++){if(c<3||c>17){lanHTML+='<div class="pt-cell pt-empty"></div>';continue}lanHTML+=cell(elMap['9-'+c])}lanHTML+='</div>';var actHTML='<div class="pt-row"><div class="pt-period-label pt-series-label">Act</div>';for(var c=1;c<=18;c++){if(c<3||c>17){actHTML+='<div class="pt-cell pt-empty"></div>';continue}actHTML+=cell(elMap['10-'+c])}actHTML+='</div>';var catOrder=['alkali','alkaline','transition','post-trans','metalloid','nonmetal','halogen','noble','lanthanide','actinide'];var legendHTML=catOrder.filter(function(cat){return C.catLabels[cat]}).map(function(cat){return '<div class="pt-legend-item"><div class="pt-legend-dot" style="background:'+C.catColors[cat]+'"></div><span>'+C.catLabels[cat]+'</span></div>'}).join('');wrapper.innerHTML='<div class="pt-outer"><div class="pt-scroll-hint">← Desliza para ver toda la tabla →</div><div class="pt-container-scroll"><div class="pt-table">'+mainHTML+'</div><div class="pt-separator"><span>Lantánidos & Actínidos</span></div><div class="pt-table pt-series">'+lanHTML+actHTML+'</div></div><div class="pt-legend">'+legendHTML+'</div><div id="el-detail" class="el-detail"></div></div>';wrapper.querySelectorAll('.pt-cell[data-z]').forEach(function(el){el.addEventListener('click',function(){showElement(parseInt(el.dataset.z))})});wrapper.querySelectorAll('.pt-ref').forEach(function(el){el.addEventListener('click',function(){wrapper.querySelector('.pt-separator').scrollIntoView({behavior:'smooth',block:'center'})})})}

function showElement(z){var el=C.elements.find(function(e){return e.z===z});if(!el)return;var d=document.getElementById('el-detail');if(!d)return;var row=el.row<=7?el.row:(el.row===9?6:7);var groupLabel=(el.row<=7)?el.col:'—';d.innerHTML='<div class="el-card-big" style="background:'+C.catColors[el.cat]+'"><span class="el-card-z">'+el.z+'</span><span class="el-card-sym">'+el.sym+'</span><span class="el-card-mass">'+el.mass+'</span></div><div class="el-card-info"><h3>'+el.name+'</h3><div class="el-card-props"><div class="el-card-prop"><span class="el-card-prop-label">Masa atómica</span><span class="el-card-prop-value">'+el.mass+' u</span></div><div class="el-card-prop"><span class="el-card-prop-label">Categoría</span><span class="el-card-prop-value">'+C.catLabels[el.cat]+'</span></div><div class="el-card-prop"><span class="el-card-prop-label">Período</span><span class="el-card-prop-value">'+row+'</span></div><div class="el-card-prop"><span class="el-card-prop-label">Grupo</span><span class="el-card-prop-value">'+groupLabel+'</span></div></div>'+(el.config?'<div class="el-card-config"><span>Configuración:</span> '+el.config+'</div>':'')+'</div><button class="el-detail-close" id="el-detail-close">✕</button>';d.classList.add('visible');d.scrollIntoView({behavior:'smooth',block:'nearest'});document.getElementById('el-detail-close').addEventListener('click',function(){d.classList.remove('visible')})}

function renderFAQs(){var list=document.getElementById('faq-list');if(!list)return;list.innerHTML=C.faqs.map(function(f,i){return '<div class="faq-item" id="faq-'+i+'"><button class="faq-q" data-faqid="'+i+'">'+f.q+'<span class="faq-chevron">▼</span></button><div class="faq-a"><div class="faq-a-inner">'+f.a+'</div></div></div>'}).join('');list.querySelectorAll('.faq-q').forEach(function(btn){btn.addEventListener('click',function(){document.getElementById('faq-'+btn.dataset.faqid).classList.toggle('open')})})}

function renderContactForm(){var container=document.getElementById('contact-form-container');if(!container)return;container.innerHTML='<div class="contact-box"><div style="display:flex;align-items:center;gap:10px;margin-bottom:14px"><div style="width:36px;height:36px;background:var(--teal);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:1rem">💬</div><div><h3>¿Dudas?</h3><p class="sub">Te responderemos.</p></div></div><form id="contact-form"><div class="form-row form-row-2"><div class="form-group"><label>Nombre</label><input type="text" required placeholder="Tu nombre"></div><div class="form-group"><label>Email</label><input type="email" required placeholder="tu@email.com"></div></div><div class="form-row"><div class="form-group"><label>Mensaje</label><textarea rows="4" required placeholder="Tu consulta..."></textarea></div></div><button type="submit" class="form-submit">📤 Enviar</button></form></div>';document.getElementById('contact-form').addEventListener('submit',function(e){e.preventDefault();container.innerHTML='<div class="contact-box"><div class="form-success"><div class="fs-icon">✅</div><h3 style="color:var(--white)">¡Enviado!</h3><p style="color:var(--text2)">Te responderemos pronto.</p><button class="btn btn-primary" id="send-another" style="margin-top:8px">Enviar otro</button></div></div>';document.getElementById('send-another').addEventListener('click',renderContactForm)})}

function openModal(id){document.getElementById(id).classList.add('open');document.body.style.overflow='hidden'}
function closeModal(id){document.getElementById(id).classList.remove('open');document.body.style.overflow=''}

function openTopic(idx){var topic=C.topics[idx];if(!topic)return;var content=document.getElementById('topic-modal-content');content.innerHTML='<div class="modal-header"><h2>'+topic.icon+' '+topic.title+'</h2><button class="modal-close" id="topic-close">✕</button></div><div class="modal-body"><p style="color:var(--text);margin-bottom:20px;line-height:1.7">'+topic.desc+'</p><h3 style="margin-bottom:12px;font-weight:700;color:var(--white)">📚 Lecciones</h3><div class="topic-lessons">'+topic.lessons.map(function(l,li){var hasContent=C.lessonContent&&C.lessonContent[l];return '<div class="topic-lesson-item'+(hasContent?' clickable':'')+'" '+(hasContent?'data-lesson="'+l+'"':'')+'><span class="tli-num">'+(li+1)+'</span><span class="tli-title">'+l+'</span>'+(hasContent?'<span class="tli-arrow">→</span>':'')+'</div>'}).join('')+'</div></div>';document.getElementById('topic-close').addEventListener('click',function(){closeModal('topic-modal')});content.querySelectorAll('.topic-lesson-item[data-lesson]').forEach(function(el){el.addEventListener('click',function(){closeModal('topic-modal');setTimeout(function(){openLesson(el.dataset.lesson)},200)})});openModal('topic-modal')}

function openLesson(lessonName){var sections=C.lessonContent?C.lessonContent[lessonName]:null;var quizQuestions=(C.quizData?C.quizData[lessonName]:null)||(C.quizData?C.quizData['_default']:null)||[];var content=document.getElementById('lesson-modal-content');var topicObj=C.topics.find(function(t){return t.lessons.indexOf(lessonName)!==-1});var topicName=topicObj?topicObj.title:'';var html='<div class="modal-header"><h2>📖 '+lessonName+'</h2><button class="modal-close" id="lesson-close">✕</button></div><div class="modal-body lesson-content"><div class="lesson-meta"><span class="lm-topic">'+topicName+'</span></div>';if(sections&&sections.length>0){sections.forEach(function(s){html+='<h3>'+s.t+'</h3><div class="lesson-section-content">'+parseMd(s.c)+'</div>'})}else{html+='<p style="color:var(--text2);text-align:center;padding:30px">Contenido en desarrollo...</p>'}if(quizQuestions.length>0){html+='<div style="margin-top:24px;padding-top:20px;border-top:1px solid var(--border)"><button class="btn btn-primary" id="start-lesson-quiz">📝 Evalúate</button></div>'}html+='</div>';content.innerHTML=html;document.getElementById('lesson-close').addEventListener('click',function(){closeModal('lesson-modal')});var quizBtn=document.getElementById('start-lesson-quiz');if(quizBtn)quizBtn.addEventListener('click',function(){startQuiz(lessonName,quizQuestions)});openModal('lesson-modal')}

function startQuiz(title,questions){var current=0,score=0;var content=document.getElementById('lesson-modal-content');function renderQuestion(){var q=questions[current];var progress=(current/questions.length)*100;content.innerHTML='<div class="modal-header"><h2>📝 Quiz: '+title+'</h2><button class="modal-close" id="quiz-close">✕</button></div><div class="modal-body"><div class="quiz-progress"><div class="quiz-progress-fill" style="width:'+progress+'%"></div></div><div style="display:flex;justify-content:space-between;margin-bottom:16px;font-size:.78rem;color:var(--text2)"><span>Pregunta '+(current+1)+' de '+questions.length+'</span><span>✅ '+score+' correctas</span></div><div style="background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:16px;margin-bottom:16px"><h3 style="font-size:.95rem;font-weight:700;color:var(--white);line-height:1.5">'+q.q+'</h3></div><div class="quiz-options">'+q.opts.map(function(opt,i){return '<button class="quiz-option" data-opt="'+i+'">'+opt+'</button>'}).join('')+'</div></div>';document.getElementById('quiz-close').addEventListener('click',function(){closeModal('lesson-modal')});content.querySelectorAll('.quiz-option').forEach(function(btn){btn.addEventListener('click',function(){var selected=parseInt(btn.dataset.opt);if(selected===q.correct)score++;content.querySelectorAll('.quiz-option').forEach(function(b,i){b.style.pointerEvents='none';if(i===q.correct){b.style.background='var(--emerald)';b.style.color='#fff';b.style.borderColor='var(--emerald)'}else if(i===selected&&selected!==q.correct){b.style.background='var(--rose)';b.style.color='#fff';b.style.borderColor='var(--rose)'}});if(q.exp){var expDiv=document.createElement('div');expDiv.style.cssText='margin-top:12px;padding:12px;background:rgba(13,148,136,.05);border:1px solid rgba(13,148,136,.12);border-radius:var(--r3);font-size:.78rem;color:var(--text);line-height:1.6';expDiv.innerHTML='<strong>💡</strong> '+q.exp;content.querySelector('.quiz-options').after(expDiv)}setTimeout(function(){current++;if(current<questions.length)renderQuestion();else showResults()},2000)})})}function showResults(){var pct=Math.round((score/questions.length)*100);content.innerHTML='<div class="modal-header"><h2>📝 Resultados</h2><button class="modal-close" id="quiz-close">✕</button></div><div class="modal-body" style="text-align:center;padding:40px 20px"><div style="font-size:3rem;margin-bottom:8px">'+(pct>=70?'🎉':'📖')+'</div><h3 style="font-weight:800;color:var(--white);font-size:1.2rem">'+(pct>=70?'¡Excelente!':'Sigue practicando')+'</h3><p style="color:var(--text2);margin:8px 0">'+score+' de '+questions.length+' correctas ('+pct+'%)</p><div style="width:100%;max-width:200px;height:8px;background:var(--border);border-radius:4px;margin:16px auto;overflow:hidden"><div style="width:'+pct+'%;height:100%;background:'+(pct>=70?'var(--emerald)':'var(--amber)')+';border-radius:4px"></div></div><button class="btn btn-primary" id="quiz-retry" style="margin-top:16px">🔄 Reintentar</button></div>';document.getElementById('quiz-close').addEventListener('click',function(){closeModal('lesson-modal')});document.getElementById('quiz-retry').addEventListener('click',function(){current=0;score=0;renderQuestion()})}renderQuestion()}

function openLab(idx){var lab=(C.labs||[])[idx];if(!lab)return;var guide=C.labGuides?C.labGuides['lab-'+idx]:null;var content=document.getElementById('lab-modal-content');var html='<div class="modal-header"><h2>'+lab.icon+' '+lab.title+'</h2><button class="modal-close" id="lab-close">✕</button></div><div class="modal-body"><p style="color:var(--text);margin-bottom:16px;line-height:1.7">'+lab.desc+'</p>';if(guide){if(guide.safety)html+='<div class="lab-safety" style="margin-bottom:16px"><strong>⚠️ Seguridad:</strong><ul style="margin-top:6px;padding-left:18px">'+guide.safety.map(function(s){return '<li style="list-style:disc;font-size:.82rem;color:var(--text);margin-bottom:4px">'+s+'</li>'}).join('')+'</ul></div>';if(guide.materials)html+='<h4 style="margin:16px 0 8px;color:var(--white)">🧪 Materiales</h4><ul class="lab-materials">'+guide.materials.map(function(m){return '<li>'+m+'</li>'}).join('')+'</ul>';if(guide.procedure)html+='<h4 style="margin:16px 0 8px;color:var(--white)">📋 Procedimiento</h4><ol class="lab-steps">'+guide.procedure.map(function(s){return '<li>'+s.p+'</li>'}).join('')+'</ol>';if(guide.obs)html+='<div class="sim-info" style="margin-top:12px"><div>📝</div><p>'+guide.obs+'</p></div>';if(guide.questions)html+='<h4 style="margin:16px 0 8px;color:var(--white)">❓ Preguntas</h4><ul style="padding-left:18px">'+guide.questions.map(function(q){return '<li style="list-style:decimal;font-size:.82rem;color:var(--text);margin-bottom:6px;line-height:1.6">'+q+'</li>'}).join('')+'</ul>'}else{html+='<p style="color:var(--text2);text-align:center;padding:20px">Guía en desarrollo...</p>'}html+='</div>';content.innerHTML=html;document.getElementById('lab-close').addEventListener('click',function(){closeModal('lab-modal')});openModal('lab-modal')}

var simEngines={'sim-ph':function(c){var pH=7;function render(){var H=Math.pow(10,-pH);var OH=Math.pow(10,-(14-pH));var type=pH<7?'Ácido':pH>7?'Básico':'Neutro';var color=pH<3?'#ef4444':pH<5?'#f97316':pH<7?'#eab308':pH===7?'#22c55e':pH<10?'#3b82f6':pH<12?'#6366f1':'#8b5cf6';c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🌡️ Medidor de pH</h4><div class="control-group"><label>pH: <span style="color:'+color+';font-weight:800">'+pH+'</span></label><input type="range" min="0" max="14" step="0.5" value="'+pH+'" id="sph-val"></div><div style="text-align:center;padding:12px;background:'+color+'20;border-radius:var(--r2);border:1px solid '+color+'40"><div style="font-size:2rem;font-weight:900;color:'+color+'">'+pH+'</div><div style="font-size:.8rem;font-weight:700;color:'+color+'">'+type+'</div></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">[H⁺]</div><div class="rb-value" style="color:var(--rose)">'+H.toExponential(2)+' M</div></div><div class="result-box"><div class="rb-label">[OH⁻]</div><div class="rb-value" style="color:var(--blue)">'+OH.toExponential(2)+' M</div></div><div class="result-box"><div class="rb-label">pOH</div><div class="rb-value" style="color:var(--indigo)">'+(14-pH).toFixed(1)+'</div></div></div><div class="ph-bar"><div class="ph-bar-track"><div class="ph-bar-indicator" style="left:'+(pH/14*100)+'%;background:'+color+'"></div></div><div class="ph-bar-labels"><span>0 (Ácido)</span><span>7 (Neutro)</span><span>14 (Básico)</span></div></div></div></div>';c.querySelector('#sph-val').addEventListener('input',function(e){pH=+e.target.value;render()})}render()},'sim-estequio':function(c){var masa=10,pmR=40,pmP=58.44;function render(){var mol=masa/pmR;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧮 Calculadora Estequiométrica</h4><div style="padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r3);margin-bottom:12px;font-size:.75rem;color:var(--text)"><strong>Reacción:</strong> NaOH + HCl → NaCl + H₂O</div><div class="control-group"><label>Masa NaOH: <span>'+masa+' g</span></label><input type="range" min="1" max="200" step="0.5" value="'+masa+'" id="se-m"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Moles</div><div class="rb-value" style="color:var(--teal)">'+mol.toFixed(4)+' mol</div></div><div class="result-box"><div class="rb-label">Masa NaCl</div><div class="rb-value" style="color:var(--blue)">'+(mol*pmP).toFixed(3)+' g</div></div><div class="result-box"><div class="rb-label">Partículas</div><div class="rb-value" style="color:var(--purple)">'+(mol*6.022e23).toExponential(3)+'</div></div></div><div class="sim-info"><div>ℹ️</div><p>n = m/PM · Relación 1:1.</p></div></div></div>';c.querySelector('#se-m').addEventListener('input',function(e){masa=+e.target.value;render()})}render()},'sim-dilucion':function(c){var M1=1,V1=100,M2=0.1;function render(){var V2=(M1*V1)/M2;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>💧 Diluciones</h4><div class="control-group"><label>M₁: <span>'+M1+' M</span></label><input type="range" min="0.1" max="10" step="0.1" value="'+M1+'" id="sd-m1"></div><div class="control-group"><label>V₁: <span>'+V1+' mL</span></label><input type="range" min="1" max="500" step="1" value="'+V1+'" id="sd-v1"></div><div class="control-group"><label>M₂: <span>'+M2+' M</span></label><input type="range" min="0.01" max="5" step="0.01" value="'+M2+'" id="sd-m2"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">V₂</div><div class="rb-value" style="color:var(--teal)">'+V2.toFixed(2)+' mL</div></div><div class="result-box"><div class="rb-label">Factor</div><div class="rb-value" style="color:var(--blue)">'+(M1/M2).toFixed(2)+'x</div></div><div class="result-box"><div class="rb-label">Agua</div><div class="rb-value" style="color:var(--purple)">'+(V2-V1).toFixed(2)+' mL</div></div></div><div class="sim-info"><div>ℹ️</div><p>M₁V₁ = M₂V₂</p></div></div></div>';c.querySelector('#sd-m1').addEventListener('input',function(e){M1=+e.target.value;render()});c.querySelector('#sd-v1').addEventListener('input',function(e){V1=+e.target.value;render()});c.querySelector('#sd-m2').addEventListener('input',function(e){M2=+e.target.value;render()})}render()},'sim-config':function(c){var Z=1;var order=['1s','2s','2p','3s','3p','4s','3d','4p','5s','4d','5p','6s','4f','5d','6p','7s','5f','6d','7p'];var maxE={s:2,p:6,d:10,f:14};var sup={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'};function toSup(n){return String(n).split('').map(function(d){return sup[d]||d}).join('')}function getConfig(z){var rem=z,res=[];for(var i=0;i<order.length&&rem>0;i++){var type=order[i][order[i].length-1];var max=maxE[type];var fill=Math.min(rem,max);res.push(order[i]+toSup(fill));rem-=fill}return res.join(' ')}function render(){var el=C.elements.find(function(e){return e.z===Z});var cfg=getConfig(Z);c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚛️ Config. Electrónica</h4><div class="control-group"><label>Z: <span style="font-weight:800;color:var(--teal)">'+Z+'</span></label><input type="range" min="1" max="36" step="1" value="'+Z+'" id="sc-z"></div>'+(el?'<div style="text-align:center;padding:14px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r2)"><div style="font-size:1.6rem;font-weight:900;color:var(--white)">'+el.sym+'</div><div style="font-size:.82rem;font-weight:600;color:var(--text)">'+el.name+'</div></div>':'')+'</div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Configuración</div><div class="rb-value" style="color:var(--teal);font-size:.8rem;word-break:break-all">'+cfg+'</div></div><div class="result-box"><div class="rb-label">Electrones</div><div class="rb-value" style="color:var(--blue)">'+Z+'</div></div></div><div class="sim-info"><div>ℹ️</div><p>Regla de Moeller: 1s→2s→2p→3s→3p→4s→3d→...</p></div></div></div>';c.querySelector('#sc-z').addEventListener('input',function(e){Z=+e.target.value;render()})}render()},'sim-nox':function(c){var compounds=[{f:'H₂O',els:[{s:'H',n:1,c:2},{s:'O',n:-2,c:1}]},{f:'NaCl',els:[{s:'Na',n:1,c:1},{s:'Cl',n:-1,c:1}]},{f:'H₂SO₄',els:[{s:'H',n:1,c:2},{s:'S',n:6,c:1},{s:'O',n:-2,c:4}]},{f:'Fe₂O₃',els:[{s:'Fe',n:3,c:2},{s:'O',n:-2,c:3}]},{f:'KMnO₄',els:[{s:'K',n:1,c:1},{s:'Mn',n:7,c:1},{s:'O',n:-2,c:4}]}];var idx=0;function render(){var cp=compounds[idx];var sum=cp.els.reduce(function(a,e){return a+e.n*e.c},0);c.innerHTML='<div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px">'+compounds.map(function(comp,i){return '<button class="nox-btn" data-idx="'+i+'" style="padding:7px 12px;border-radius:var(--r3);font-weight:700;font-size:.78rem;cursor:pointer;border:1px solid '+(i===idx?'var(--indigo)':'var(--border)')+';min-height:36px;background:'+(i===idx?'var(--indigo)':'none')+';color:'+(i===idx?'#fff':'var(--text)')+'">'+comp.f+'</button>'}).join('')+'</div><div style="background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:18px;text-align:center"><h4 style="font-size:1.2rem;font-weight:800;margin-bottom:14px;color:var(--white)">'+cp.f+'</h4><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-bottom:12px">'+cp.els.map(function(e){return '<div style="background:var(--card);border:1px solid var(--border);border-radius:var(--r2);padding:10px 14px;text-align:center;min-width:60px"><div style="font-size:1.2rem;font-weight:800;color:var(--white)">'+e.s+'</div><div style="font-size:.9rem;font-weight:700;margin-top:3px;color:'+(e.n>=0?'var(--blue)':'#ef4444')+'">'+(e.n>0?'+':'')+e.n+'</div><div style="font-size:.55rem;color:var(--text2);margin-top:1px">×'+e.c+'</div></div>'}).join('')+'</div><div style="font-size:.78rem;color:var(--text2)">Σ = <strong style="color:var(--teal)">'+sum+'</strong> '+(sum===0?'✅':'')+'</div></div>';c.querySelectorAll('.nox-btn').forEach(function(btn){btn.addEventListener('click',function(){idx=parseInt(btn.dataset.idx);render()})})}render()},'sim-disol':function(c){var ms=4,pm=40,vs=100,msv=100,nH=1;function render(){var mol=ms/pm;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧫 Concentración</h4><div class="control-group"><label>Masa: <span>'+ms+' g</span></label><input type="range" min="0.1" max="100" step="0.1" value="'+ms+'" id="sd-ms"></div><div class="control-group"><label>PM: <span>'+pm+'</span></label><input type="range" min="1" max="500" step="1" value="'+pm+'" id="sd-pm"></div><div class="control-group"><label>Vol: <span>'+vs+' mL</span></label><input type="range" min="10" max="2000" step="10" value="'+vs+'" id="sd-vs"></div><div class="control-group"><label>Solvente: <span>'+msv+' g</span></label><input type="range" min="10" max="2000" step="10" value="'+msv+'" id="sd-msv"></div><div class="control-group"><label>n: <span>'+nH+'</span></label><input type="range" min="1" max="3" step="1" value="'+nH+'" id="sd-nh"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Moles</div><div class="rb-value" style="color:var(--teal)">'+mol.toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">M</div><div class="rb-value" style="color:var(--blue)">'+(mol/(vs/1000)).toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">N</div><div class="rb-value" style="color:var(--purple)">'+(mol/(vs/1000)*nH).toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">m</div><div class="rb-value" style="color:var(--orange)">'+(mol/(msv/1000)).toFixed(4)+'</div></div></div></div></div>';c.querySelector('#sd-ms').addEventListener('input',function(e){ms=+e.target.value;render()});c.querySelector('#sd-pm').addEventListener('input',function(e){pm=+e.target.value;render()});c.querySelector('#sd-vs').addEventListener('input',function(e){vs=+e.target.value;render()});c.querySelector('#sd-msv').addEventListener('input',function(e){msv=+e.target.value;render()});c.querySelector('#sd-nh').addEventListener('input',function(e){nH=+e.target.value;render()})}render()},'sim-tit':function(c){var vol=0,Ca=0.1,Va=25,Cb=0.1;function calcPH(v){var mA=Ca*Va/1000,mB=Cb*v/1000;if(mB<mA){var ex=mA-mB;return -Math.log10(ex/((Va+v)/1000))}if(Math.abs(mB-mA)<0.0001)return 7;var ex2=mB-mA;return 14+Math.log10(ex2/((Va+v)/1000))}function render(){var pH=calcPH(vol);var veq=(Ca*Va)/Cb;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧪 Titulación</h4><div style="padding:8px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r3);margin-bottom:10px;font-size:.72rem;color:var(--text)">HCl '+Ca+'M ('+Va+' mL) + NaOH '+Cb+'M</div><div class="control-group"><label>Vol NaOH: <span>'+vol+' mL</span></label><input type="range" min="0" max="50" step="0.5" value="'+vol+'" id="st-v"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">pH</div><div class="rb-value" style="color:'+(pH<7?'var(--rose)':pH>7?'var(--blue)':'var(--emerald)')+'">'+pH.toFixed(2)+'</div></div><div class="result-box"><div class="rb-label">V equiv.</div><div class="rb-value" style="color:var(--purple)">'+veq.toFixed(1)+' mL</div></div><div class="result-box"><div class="rb-label">Estado</div><div class="rb-value" style="color:var(--teal);font-size:.75rem">'+(vol<veq?'Antes PE':vol>veq?'Después PE':'¡Punto equiv.!')+'</div></div></div></div></div>';c.querySelector('#st-v').addEventListener('input',function(e){vol=+e.target.value;render()})}render()},'sim-valor':function(c){var Cb=0.1,Vb=25,Va=20;function render(){var Ca=(Cb*Vb)/Va;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚗️ Valoración</h4><div class="control-group"><label>C_base: <span>'+Cb+' M</span></label><input type="range" min="0.01" max="1" step="0.01" value="'+Cb+'" id="sv-cb"></div><div class="control-group"><label>V_base: <span>'+Vb+' mL</span></label><input type="range" min="0.5" max="50" step="0.5" value="'+Vb+'" id="sv-vb"></div><div class="control-group"><label>V_ácido: <span>'+Va+' mL</span></label><input type="range" min="1" max="100" step="1" value="'+Va+'" id="sv-va"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">C_ácido</div><div class="rb-value" style="color:var(--teal)">'+Ca.toFixed(4)+' M</div></div><div class="result-box"><div class="rb-label">°Dornic</div><div class="rb-value" style="color:var(--rose)">'+(Ca*100*1000/10).toFixed(1)+'</div></div><div class="result-box"><div class="rb-label">mol base</div><div class="rb-value" style="color:var(--blue)">'+(Cb*Vb/1000).toExponential(3)+'</div></div></div></div></div>';c.querySelector('#sv-cb').addEventListener('input',function(e){Cb=+e.target.value;render()});c.querySelector('#sv-vb').addEventListener('input',function(e){Vb=+e.target.value;render()});c.querySelector('#sv-va').addEventListener('input',function(e){Va=+e.target.value;render()})}render()},'sim-glosario':function(c){var terms=[{t:'Ácido',d:'Dona protones (H⁺) según Brønsted-Lowry.'},{t:'Base',d:'Acepta protones (H⁺) según Brønsted-Lowry.'},{t:'pH',d:'pH = -log[H⁺]. Escala 0-14.'},{t:'Mol',d:'6.022 × 10²³ entidades.'},{t:'Molaridad (M)',d:'mol/L de solución.'},{t:'Normalidad (N)',d:'eq-g/L. N = M × factor.'},{t:'Molalidad (m)',d:'mol/kg solvente.'},{t:'Valoración',d:'Determina concentración desconocida.'},{t:'Indicador',d:'Cambia color según pH.'},{t:'Punto de equivalencia',d:'mol ácido = mol base.'},{t:'Estequiometría',d:'Cálculo de cantidades en reacciones.'},{t:'Reactivo limitante',d:'Se consume primero.'}];var search='';function render(){var filtered=terms.filter(function(t){return t.t.toLowerCase().indexOf(search.toLowerCase())!==-1||t.d.toLowerCase().indexOf(search.toLowerCase())!==-1});c.innerHTML='<div style="margin-bottom:16px"><input type="text" placeholder="🔍 Buscar..." value="'+search+'" id="sg-search" style="width:100%;padding:10px 14px;border:1px solid var(--border);border-radius:var(--r3);font-size:.82rem;color:var(--text);background:var(--bg)"></div><div style="display:flex;flex-direction:column;gap:6px">'+filtered.map(function(t){return '<div style="padding:12px 14px;background:var(--card);border:1px solid var(--border);border-radius:var(--r3)"><strong style="color:var(--white);font-size:.85rem">'+t.t+'</strong><p style="color:var(--text);font-size:.78rem;margin-top:4px;line-height:1.55">'+t.d+'</p></div>'}).join('')+'</div>';c.querySelector('#sg-search').addEventListener('input',function(e){search=e.target.value;render()})}render()}};

function openSim(id){var sim=C.simulations.find(function(s){return s.id===id});var csim=(C.customSims||[]).find(function(s){return s.id===id});var target=sim||csim;if(!target)return;var mc=document.getElementById('sim-modal-content');mc.innerHTML='<div class="modal-header"><h2>'+target.icon+' '+target.title+'</h2><button class="modal-close" id="sim-close">✕</button></div>';var bd=document.createElement('div');bd.className='modal-body';mc.appendChild(bd);if(simEngines[id])simEngines[id](bd);else if(csim)buildCustomSim(csim,bd);else bd.innerHTML='<p style="text-align:center;padding:40px;color:var(--text2)">En desarrollo...</p>';document.getElementById('sim-close').addEventListener('click',function(){closeModal('sim-modal')});openModal('sim-modal')}

function buildCustomSim(cfg,container){var state={};cfg.inputs.forEach(function(inp){state[inp.key]=inp.default||0});function calc(formula){try{var fn=new Function(Object.keys(state).join(','),'return '+formula);return fn.apply(null,Object.values(state))||0}catch(e){return 0}}function render(){container.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚙️ Parámetros</h4>'+cfg.inputs.map(function(inp){return '<div class="control-group"><label>'+inp.label+': <span>'+state[inp.key]+' '+inp.unit+'</span></label><input type="range" min="'+inp.min+'" max="'+inp.max+'" step="'+inp.step+'" value="'+state[inp.key]+'" data-key="'+inp.key+'"></div>'}).join('')+'</div><div><div class="results-grid" style="margin-top:0;margin-bottom:14px">'+cfg.outputs.map(function(out){var val=calc(out.formula);return '<div class="result-box"><div class="rb-label">'+out.label+'</div><div class="rb-value" style="color:'+(out.color||'var(--teal)')+'">'+val.toFixed(out.decimals||3)+' '+out.unit+'</div></div>'}).join('')+'</div>'+(cfg.info?'<div class="sim-info"><div>ℹ️</div><p>'+cfg.info+'</p></div>':'')+'</div></div>';container.querySelectorAll('input[type="range"]').forEach(function(el){el.addEventListener('input',function(){state[el.dataset.key]=+el.value;render()})})}render()}

function openVideo(id,title){var mc=document.getElementById('video-modal-content');mc.innerHTML='<div class="modal-header"><h2>'+title+'</h2><button class="modal-close" id="video-close">✕</button></div><div class="modal-body"><div class="vm-iframe"><iframe src="https://www.youtube.com/embed/'+id+'?autoplay=1&playsinline=1" allow="autoplay;encrypted-media" allowfullscreen></iframe></div></div>';document.getElementById('video-close').addEventListener('click',closeVideo);openModal('video-modal')}
function closeVideo(){var mc=document.getElementById('video-modal-content');var iframe=mc.querySelector('iframe');if(iframe)iframe.remove();closeModal('video-modal')}

var adminTabs=[{key:'site',label:'🏠 General'},{key:'hero',label:'🎯 Portada'},{key:'topics',label:'📚 Temas'},{key:'raw',label:'🔧 Avanzado'}];var activeTab=0,adminAuth=false;
function openAdmin(){if(!adminAuth){var p=prompt('🔒 Contraseña:');if(p!==C.admin.password){if(p!==null)toast('❌ Incorrecta');return}adminAuth=true}document.getElementById('admin-overlay').classList.add('open');document.body.style.overflow='hidden';drawAdmin()}
function closeAdmin(){document.getElementById('admin-overlay').classList.remove('open');document.body.style.overflow=''}
function toast(m){var d=document.createElement('div');d.className='atoast';d.textContent=m;document.body.appendChild(d);setTimeout(function(){d.remove()},2500)}
function drawAdmin(){var tabsEl=document.getElementById('admin-tabs');var body=document.getElementById('admin-body');if(!tabsEl||!body)return;tabsEl.innerHTML=adminTabs.map(function(t,i){return '<button class="admin-tab'+(i===activeTab?' active':'')+'" data-tabidx="'+i+'">'+t.label+'</button>'}).join('');tabsEl.querySelectorAll('.admin-tab').forEach(function(btn){btn.addEventListener('click',function(){activeTab=parseInt(btn.dataset.tabidx);drawAdmin()})});var k=adminTabs[activeTab].key;var info=function(text){return '<div class="ainfo"><span>💡</span><span>'+text+'</span></div>'};if(k==='site')body.innerHTML=info('<b>Datos generales</b>')+'<div class="ae"><label>Nombre</label><input id="as-name" value="'+C.site.name+'"></div><div class="ae"><label>Descripción</label><textarea id="as-desc" rows="3">'+C.site.description+'</textarea></div><div class="ae"><label>Año</label><input id="as-year" value="'+C.site.year+'"></div>';else if(k==='hero')body.innerHTML=info('<b>Portada</b>')+'<div class="ae"><label>Badge</label><input id="ah-badge" value="'+C.hero.badge+'"></div><div class="ae"><label>Título</label><textarea id="ah-title" rows="3">'+C.hero.title+'</textarea></div><div class="ae"><label>Subtítulo</label><textarea id="ah-sub" rows="3">'+C.hero.subtitle+'</textarea></div>';else if(k==='topics')body.innerHTML=info('<b>Temas</b>')+C.topics.map(function(t,i){return '<div class="acard"><div class="acard-head"><h4><span class="acard-num">'+(i+1)+'</span>'+t.icon+' '+t.title+'</h4></div><div class="ae"><label>Emoji</label><input id="at-ic-'+i+'" value="'+t.icon+'" style="text-align:center;font-size:1.2rem"></div><div class="ae"><label>Título</label><input id="at-ti-'+i+'" value="'+t.title+'"></div><div class="ae"><label>Descripción</label><textarea id="at-de-'+i+'" rows="3">'+t.desc+'</textarea></div><div class="ae"><label>Lecciones</label><textarea id="at-le-'+i+'" rows="3">'+t.lessons.join('\n')+'</textarea></div></div>'}).join('');else if(k==='raw')body.innerHTML=info('⚠️ <b>JSON completo</b>')+'<div class="ae"><label>CONFIG</label><textarea id="admin-raw" style="min-height:400px;font-family:monospace;font-size:.72rem">'+JSON.stringify(CONFIG,null,2)+'</textarea></div>'}
function applyAdminChanges(){try{var k=adminTabs[activeTab].key;if(k==='site'){C.site.name=document.getElementById('as-name').value;C.site.description=document.getElementById('as-desc').value;C.site.year=document.getElementById('as-year').value}else if(k==='hero'){C.hero.badge=document.getElementById('ah-badge').value;C.hero.title=document.getElementById('ah-title').value;C.hero.subtitle=document.getElementById('ah-sub').value}else if(k==='topics'){C.topics.forEach(function(t,i){var ic=document.getElementById('at-ic-'+i),ti=document.getElementById('at-ti-'+i),de=document.getElementById('at-de-'+i),le=document.getElementById('at-le-'+i);if(ic)t.icon=ic.value;if(ti)t.title=ti.value;if(de)t.desc=de.value;if(le)t.lessons=le.value.split('\n').filter(function(x){return x.trim()})})}else if(k==='raw'){var parsed=JSON.parse(document.getElementById('admin-raw').value);Object.keys(parsed).forEach(function(key){CONFIG[key]=parsed[key]})}buildApp();setupEventListeners();enhanceLayout();toast('✅ Aplicado')}catch(err){alert('❌ Error: '+err.message)}}
function downloadConfig(){var c='const CONFIG = '+JSON.stringify(CONFIG,null,2)+';\n';var b=new Blob([c],{type:'application/javascript'});var u=URL.createObjectURL(b);var a=document.createElement('a');a.href=u;a.download='config.js';a.click();URL.revokeObjectURL(u)}

function enhanceLayout(){var hero=document.querySelector('.hero');if(hero){var stats=hero.querySelector('.hero-stats');if(stats){var bar=document.createElement('div');bar.className='hero-bar';bar.innerHTML='<div class="hero-bar-inner"><div class="hero-bar-stats">'+C.hero.stats.map(function(s){var p=s.text.split(' ');return '<div class="hb-stat"><span class="hb-num">'+p[0]+'</span><span class="hb-label">'+p.slice(1).join(' ')+'</span></div>'}).join('')+'</div><div class="hero-bar-credit"><span>Cátedra del</span><strong>Prof. Wilmer Molina</strong></div></div>';stats.replaceWith(bar)}}var footer=document.querySelector('footer');if(footer)footer.innerHTML='<div class="container"><div class="ft-top"><div class="ft-brand"><div class="logo"><div class="logo-icon">⚗️</div><span class="logo-text">'+C.site.name+'</span></div><p class="ft-desc">'+C.footer.description+'</p></div><div class="ft-cols">'+C.footer.columns.map(function(col){return '<div class="ft-col"><h4>'+col.title+'</h4><ul>'+col.links.map(function(l){return '<li><a href="#">'+l+'</a></li>'}).join('')+'</ul></div>'}).join('')+'</div></div><div class="ft-mid"><div class="ft-team"><div class="ft-person"><div class="ft-avatar">👨‍🏫</div><div><strong>Prof. Wilmer Molina</strong><span>Docente de Química General</span></div></div><div class="ft-person"><div class="ft-avatar">💻</div><div><strong>Jimmy Bracho</strong><span>Desarrollo Web</span></div></div></div></div><div class="ft-bottom"><p class="copy">© '+C.site.year+' '+C.site.name+' — Todos los derechos reservados</p><div class="socials">'+C.footer.socials.map(function(s){return '<a href="'+s.url+'" class="social-link">'+s.label+'</a>'}).join('')+'</div></div></div>'}

function scrollToSection(id){var el=document.getElementById(id);if(!el)return;var y=el.getBoundingClientRect().top+window.scrollY-56;window.scrollTo({top:y,behavior:'smooth'})}
var tabSectionMap={topics:'tab-topics',simulations:'tab-sims',labs:'tab-labs',videos:'tab-videos'};
function handleNavClick(sectionId){var tabId=tabSectionMap[sectionId];if(tabId){switchHubTab(tabId);scrollToSection('topics')}else{scrollToSection(sectionId)}}
function switchHubTab(tabId){document.querySelectorAll('.hub-tab').forEach(function(t){t.classList.toggle('active',t.dataset.tab===tabId)});document.querySelectorAll('.hub-panel').forEach(function(p){p.classList.toggle('active',p.id===tabId)})}
function toggleQuickNav(){var panel=document.getElementById('quicknav-panel');var fab=document.getElementById('quicknav-fab');if(!panel||!fab)return;var open=panel.classList.toggle('open');fab.textContent=open?'✕':'⚡';fab.classList.toggle('open',open)}
function closeQuickNav(){var panel=document.getElementById('quicknav-panel');var fab=document.getElementById('quicknav-fab');if(!panel||!fab)return;panel.classList.remove('open');fab.classList.remove('open');fab.textContent='⚡'}
function toggleFeedback(){var p=document.getElementById('feedback-panel');if(!p)return;var open=p.classList.toggle('open');var fab=document.getElementById('feedback-fab');if(fab)fab.textContent=open?'✕':'💬'}
function submitFeedback(){var t=document.getElementById('feedback-text');if(!t||!t.value.trim())return;var body=document.getElementById('feedback-body');body.innerHTML='<div style="text-align:center;padding:18px"><div style="font-size:2rem;margin-bottom:6px">✅</div><h3 style="font-weight:700;color:var(--white)">¡Gracias!</h3><p style="font-size:.78rem;color:var(--text2)">Comentario enviado.</p></div>';setTimeout(function(){toggleFeedback();setTimeout(function(){body.innerHTML='<div class="feedback-type"><button type="button" class="active" data-type="error">🐛 Error</button><button type="button" data-type="sugerencia">💡 Sugerencia</button></div><textarea class="feedback-textarea" id="feedback-text" placeholder="Describe el error o tu sugerencia..."></textarea><button class="feedback-submit" id="feedback-submit-btn">Enviar</button>';body.querySelectorAll('.feedback-type button').forEach(function(btn){btn.addEventListener('click',function(){body.querySelectorAll('.feedback-type button').forEach(function(b){b.classList.remove('active')});btn.classList.add('active')})});document.getElementById('feedback-submit-btn').addEventListener('click',submitFeedback)},400)},2000)}

function setupEventListeners(){document.getElementById('topbar-toggle').addEventListener('click',function(){document.getElementById('sidebar').classList.toggle('open')});document.getElementById('sb-overlay').addEventListener('click',function(){document.getElementById('sidebar').classList.remove('open')});document.querySelectorAll('.sb-link').forEach(function(link){link.addEventListener('click',function(){handleNavClick(link.dataset.section);document.getElementById('sidebar').classList.remove('open')})});document.querySelectorAll('.hero-actions .btn').forEach(function(btn){btn.addEventListener('click',function(){handleNavClick(btn.dataset.action)})});document.querySelectorAll('.topbar-link').forEach(function(btn){btn.addEventListener('click',function(){handleNavClick(btn.dataset.section)})});document.querySelectorAll('.hub-tab').forEach(function(tab){tab.addEventListener('click',function(){switchHubTab(tab.dataset.tab)})});document.getElementById('quicknav-fab').addEventListener('click',toggleQuickNav);document.querySelectorAll('.quicknav-item').forEach(function(item){item.addEventListener('click',function(){handleNavClick(item.dataset.section);closeQuickNav()})});document.getElementById('backtop-btn').addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});window.addEventListener('scroll',function(){var btn=document.getElementById('backtop-btn');if(btn)btn.classList.toggle('visible',window.scrollY>500)},{passive:true});document.addEventListener('click',function(e){['topic-modal','lesson-modal','lab-modal','sim-modal','video-modal'].forEach(function(id){if(e.target.id===id){if(id==='video-modal')closeVideo();else closeModal(id)}});var qnPanel=document.getElementById('quicknav-panel');var qnFab=document.getElementById('quicknav-fab');if(qnPanel&&qnPanel.classList.contains('open')&&!qnPanel.contains(e.target)&&e.target!==qnFab)closeQuickNav()});document.getElementById('feedback-fab').addEventListener('click',toggleFeedback);document.querySelectorAll('.feedback-type button').forEach(function(btn){btn.addEventListener('click',function(){document.querySelectorAll('.feedback-type button').forEach(function(b){b.classList.remove('active')});btn.classList.add('active')})});document.getElementById('feedback-submit-btn').addEventListener('click',submitFeedback);document.addEventListener('keydown',function(e){if(e.ctrlKey&&e.shiftKey&&(e.key==='Q'||e.key==='q')){e.preventDefault();document.getElementById('admin-overlay').classList.contains('open')?closeAdmin():openAdmin()}if(e.key==='Escape'){if(document.getElementById('admin-overlay').classList.contains('open')){closeAdmin();return}var openOverlay=document.querySelector('.modal-overlay.open');if(openOverlay){if(openOverlay.id==='video-modal')closeVideo();else closeModal(openOverlay.id)}if(document.getElementById('feedback-panel').classList.contains('open'))toggleFeedback();if(document.getElementById('quicknav-panel').classList.contains('open'))closeQuickNav()}});document.getElementById('admin-apply').addEventListener('click',applyAdminChanges);document.getElementById('admin-download').addEventListener('click',downloadConfig);document.getElementById('admin-close').addEventListener('click',closeAdmin);var touchStartY=0;document.addEventListener('touchstart',function(e){touchStartY=e.touches[0].clientY},{passive:true});document.addEventListener('touchend',function(e){if(e.changedTouches[0].clientY-touchStartY>120){var o=document.querySelector('.modal-overlay.open');if(o){if(o.id==='video-modal')closeVideo();else closeModal(o.id)}}},{passive:true})}

